[CmdletBinding()]
param([ValidateSet('broker-pause','inspect','prepare-reset','collect')][string]$Action,[string]$Nonce,[int]$OwnerPid)
$ErrorActionPreference='Stop'
if($env:COMPUTERNAME -ne 'MU-CLEAN-LAB' -or (Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion').EditionID -ne 'IoTEnterpriseSEval' -or -not (Test-Path -LiteralPath C:\MuLab\public\provisioned.json)){throw 'Only the dedicated disconnected evaluation guest may run this operator'}
if(-not ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)){throw 'Synthetic evaluation administrator required'}
$sid=(Get-LocalUser MuLabUser).SID.Value;$common=Join-Path $env:ProgramData MuCodeSandbox-HyperVBroker-v1;$root=Join-Path $common ('users/'+$sid)
function Receipt([string]$name,$value){if($Nonce -notmatch '^[a-f0-9]{64}$'){throw 'Bound owner nonce required'};$value.nonce=$Nonce;[IO.File]::WriteAllText(('C:\MuLab\approved\power-'+$name+'.json'),($value|ConvertTo-Json -Depth 8 -Compress))}
if($Action -eq 'prepare-reset'){
 if(@(Get-CimInstance Win32_Process -Filter "Name='node.exe'"|Where-Object{$_.CommandLine -like '*client.mjs*power-*'}).Count){throw 'A power diagnostic client is still live'}
 $registry=Get-Content -LiteralPath (Join-Path $root vms.json) -Raw|ConvertFrom-Json;$records=@($registry.records.PSObject.Properties);$vms=@(Get-VM);if(-not $records.Count -or $records.Count -gt 8 -or $records.Count -ne $vms.Count -or @($vms|Where-Object{$_.State -ne 'Off'}).Count){throw 'Only a bounded stopped synthetic set may be reset'}
 $known=@{};foreach($directory in @(Get-ChildItem -LiteralPath C:\MuLab\public -Directory -Filter 'power-app-*')){if($directory.Name -notmatch '^power-app-[a-f0-9]{16}$'){throw 'Unexpected diagnostic app directory'};$db=Join-Path $directory.FullName state.sqlite;if(-not (Test-Path -LiteralPath $db)){continue};$code="const {DatabaseSync}=require('node:sqlite');const db=new DatabaseSync(process.argv[1],{readOnly:true});process.stdout.write(JSON.stringify(db.prepare('SELECT config FROM environments').all().map(r=>JSON.parse(r.config))));db.close()";$rows=(& C:\MuLab\product\resources\node\node.exe --no-warnings -e $code $db|Out-String)|ConvertFrom-Json;foreach($row in $rows){if($row.name -ne 'Synthetic native power continuity' -or $row.kind -ne 'vm' -or $row.network.host -ne '127.0.0.1' -or $row.network.egressLock.expectedIp -ne '203.0.113.10'){throw 'Unexpected environment in a diagnostic profile'};$known[$row.id]=$row}}
 $base=Get-Content -LiteralPath C:\MuLab\images\base.json -Raw|ConvertFrom-Json;$configs=@();foreach($entry in $records){$record=$entry.Value;$row=$known[$entry.Name];$vm=@($vms|Where-Object{[string]$_.Id -eq $record.platformId});if(-not $row -or $record.ownerSid -ne $sid -or $record.imageSha256 -ne $base.imageSha256 -or $row.cpus -ne 2 -or $row.memoryGiB -ne 4 -or $row.diskGiB -ne 32 -or $vm.Count -ne 1 -or $vm[0].Name -ne ('mu-win-'+$entry.Name.Replace('-','')) -or $vm[0].Notes -ne ('MuCodeSandbox Windows preview '+$vm[0].Name)){throw 'A retained VM is not attributable to the failed synthetic tests'};$configs+=@{version=1;id=$entry.Name;cpus=2;memoryGiB=4;diskGiB=32;timezone='UTC';image=$base.image;imageSha256=$base.imageSha256;proxy=@{mode='http';address='127.0.0.1';port=9};expectedIp='203.0.113.90'}}
 [IO.File]::WriteAllText('C:\MuLab\approved\power-failed-reset.json',(@{syntheticOnly=$true;configs=$configs}|ConvertTo-Json -Depth 8 -Compress));return @{syntheticOnly=$true;stoppedAllocations=$configs.Count}
}
if($Action -eq 'inspect'){
 $jobs=$null;if(Test-Path -LiteralPath C:\MuLab\public\power-run-owner.json){$owner=Get-Content -LiteralPath C:\MuLab\public\power-run-owner.json -Raw|ConvertFrom-Json;if($owner.nonce -match '^[a-f0-9]{64}$'){$db='C:\MuLab\public\power-app-'+$owner.nonce.Substring(0,16)+'\state.sqlite';if(Test-Path -LiteralPath $db){$code="const {DatabaseSync}=require('node:sqlite');const db=new DatabaseSync(process.argv[1],{readOnly:true});process.stdout.write(JSON.stringify(db.prepare('SELECT status,message FROM jobs ORDER BY created_at DESC LIMIT 4').all()));db.close()";$jobs=(& C:\MuLab\product\resources\node\node.exe --no-warnings -e $code $db|Out-String)|ConvertFrom-Json}}}
 return @{agents=@(Get-CimInstance Win32_Process|Where-Object{$_.Name -like 'hv-broker-*' -or $_.Name -like 'hv-channel-*'}|Select-Object ProcessId,ExecutablePath,CommandLine);meta=$(Get-Content -LiteralPath (Join-Path $common 'bin/current.json') -Raw|ConvertFrom-Json);registry=$(Get-Content -LiteralPath (Join-Path $root 'vms.json') -Raw|ConvertFrom-Json);request=$(if(Test-Path -LiteralPath C:\MuLab\public\power-pause-request.json){Get-Content -LiteralPath C:\MuLab\public\power-pause-request.json -Raw|ConvertFrom-Json}else{$null});jobs=$jobs;vms=@(Get-VM|Select-Object Name,@{Name='state';Expression={[string]$_.State}});clients=@(Get-CimInstance Win32_Process -Filter "Name='node.exe'"|Where-Object{$_.CommandLine -like '*client.mjs*power-*'}|Select-Object ProcessId,CreationDate);results=@(Get-ChildItem -LiteralPath C:\MuLab\public -Filter 'power-*-result.json'|ForEach-Object{Get-Content -LiteralPath $_.FullName -Raw|ConvertFrom-Json});trip=$(if(Test-Path -LiteralPath (Join-Path $root power-trip.json)){Get-Content -LiteralPath (Join-Path $root power-trip.json) -Raw|ConvertFrom-Json}else{$null});errors=$(if(Test-Path -LiteralPath (Join-Path $root broker-errors.log)){Get-Content -LiteralPath (Join-Path $root broker-errors.log) -Tail 24|Out-String}else{$null})}
}
if($Action -eq 'collect'){
 $results=@{};foreach($phase in @('power-run','power-recover')){$r=Get-Content -LiteralPath ('C:\MuLab\approved\'+$phase+'-result.json') -Raw|ConvertFrom-Json;if(-not $r.complete){throw ('Incomplete native continuity acceptance: '+$phase)};$results[$phase]=$r}
 if(-not $results['power-recover'].nested.removed -or $results['power-run'].nested.config.id -ne $results['power-recover'].nested.id -or $results['power-run'].nested.platformId -ne $results['power-recover'].nested.platformId -or @(Get-VM).Count){throw 'Native continuity cleanup or identity confirmation is incomplete'}
 $registry=Get-Content -LiteralPath (Join-Path $root vms.json) -Raw|ConvertFrom-Json;if(@($registry.records.PSObject.Properties).Count -or [IO.File]::ReadAllText((Join-Path $root vms.json)) -cne [IO.File]::ReadAllText((Join-Path $root vms.backup.json))){throw 'Final protected registrations must be empty and matching'}
 $winlogon='HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Winlogon';if((Get-ItemProperty -LiteralPath $winlogon).DefaultUserName -ne 'MuLabUser'){throw 'Synthetic account identity changed'};Remove-ItemProperty -LiteralPath $winlogon -Name DefaultPassword -ErrorAction SilentlyContinue;Set-ItemProperty -LiteralPath $winlogon -Name AutoAdminLogon -Value '0' -Type String;Set-ItemProperty -LiteralPath $winlogon -Name AutoLogonCount -Value 0 -Type DWord
 $hashes=@{};foreach($file in @('C:\MuLab\client.mjs','C:\MuLab\power-client.mjs','C:\MuLab\product\resources\app\dist-server\native\windows\HyperVBroker.cs','C:\MuLab\product\resources\app\dist-server\native\windows\HyperVChannel.cs','C:\MuLab\product\resources\app\dist-server\native\windows\PowerWatch.cs','C:\MuLab\product\resources\app\dist-server\native\windows\PowerProtection.cs','C:\MuLab\product\resources\app\dist-server\scripts\windows\build-channel.ps1','C:\MuLab\product\resources\app\dist-server\scripts\windows\build-broker.ps1','C:\MuLab\product\resources\app\dist-server\server\platform\windows\runtime.js','C:\MuLab\product\resources\app\dist-server\server\platform\windows\broker.js','C:\MuLab\product\resources\app\dist-server\server\platform\windows\power.js','C:\MuLab\product\resources\app\dist-server\server\platform\windows\manager.js','C:\MuLab\product\resources\app\dist-server\server\platform\windows\service.js')){$hashes[$file]=(Get-FileHash -LiteralPath $file).Hash.ToLowerInvariant()}
 return @{results=$results;sourceHashes=$hashes;nestedGuestsRemaining=0;syntheticAutologonDisabled=$true;originalCanaryPreserved=$true;actualOsSleepTested=$false;actualBrokerThreadPauseTested=$true;aiWebsitesVisited=0}
}
if($Nonce -notmatch '^[a-f0-9]{64}$' -or $OwnerPid -le 0){throw 'Bound synthetic owner required'}
$owner=Get-CimInstance Win32_Process -Filter ('ProcessId='+$OwnerPid);if($owner.ExecutablePath -ne 'C:\MuLab\product\resources\node\node.exe' -or (Invoke-CimMethod -InputObject $owner -MethodName GetOwnerSid).Sid -ne $sid -or $owner.CommandLine -notlike '*client.mjs power-run*'){throw 'Only the bound ordinary diagnostic client may request the fault'}
$request=Get-Content -LiteralPath C:\MuLab\public\power-pause-request.json -Raw|ConvertFrom-Json;if($request.nonce -ne $Nonce -or $request.action -ne 'broker-pause' -or $request.id -notmatch '^[a-f0-9-]{36}$'){throw 'Typed synthetic pause request changed'}
$registry=Get-Content -LiteralPath (Join-Path $root vms.json) -Raw|ConvertFrom-Json;$records=@($registry.records.PSObject.Properties);$vms=@(Get-VM -ErrorAction Stop)
if($records.Count -ne 1 -or $records[0].Name -ne $request.id -or $records[0].Value.ownerSid -ne $sid -or $vms.Count -ne 1 -or [string]$vms[0].Id -ne $records[0].Value.platformId -or $vms[0].Name -ne ('mu-win-'+$request.id.Replace('-','')) -or $vms[0].State -ne 'Running' -or $vms[0].Notes -ne ('MuCodeSandbox Windows preview '+$vms[0].Name)){throw 'Only the single owned running synthetic VM may be exercised'}
$bin=Join-Path $common bin;$meta=Get-Content -LiteralPath (Join-Path $bin current.json) -Raw|ConvertFrom-Json;$expected=Join-Path $bin $meta.brokerFile
Add-Type -TypeDefinition @'
using System;using System.Runtime.InteropServices;
public static class MuSyntheticCommandLine {
 [DllImport("shell32.dll",CharSet=CharSet.Unicode,SetLastError=true)] static extern IntPtr CommandLineToArgvW(string command,out int count);
 [DllImport("kernel32.dll")] static extern IntPtr LocalFree(IntPtr value);
 public static string[] Read(string command){int count;var pointer=CommandLineToArgvW(command,out count);if(pointer==IntPtr.Zero||count>16)throw new Exception("Invalid diagnostic command line");try{var result=new string[count];for(int i=0;i<count;i++)result[i]=Marshal.PtrToStringUni(Marshal.ReadIntPtr(pointer,i*IntPtr.Size));return result;}finally{LocalFree(pointer);}}
}
'@
$inventory=@(Get-CimInstance Win32_Process|Where-Object{$_.Name -eq $meta.brokerFile});$agents=@($inventory|Where-Object{$commandParts=[MuSyntheticCommandLine]::Read($_.CommandLine);$commandParts.Count -eq 6 -and [IO.Path]::GetFileName($commandParts[0]) -eq $meta.brokerFile -and $commandParts[1] -eq '--owner' -and $commandParts[2] -eq [string]$OwnerPid -and $commandParts[3] -eq '--pipe' -and $commandParts[4] -eq $Nonce -and $commandParts[5] -eq '--detect-host'})
if($agents.Count -ne 1 -or (Get-FileHash -LiteralPath $expected).Hash.ToLowerInvariant() -ne $meta.brokerSha256){[IO.File]::WriteAllText('C:\MuLab\private\power-agent-mismatch.json',(@{ownerPid=$OwnerPid;nonce=$Nonce;expected=$expected;inventory=@($inventory|Select-Object ProcessId,Name,ExecutablePath,CommandLine)}|ConvertTo-Json -Depth 5));throw 'The exact protected diagnostic broker is unavailable'}
$agent=[Diagnostics.Process]::GetProcessById([int]$agents[0].ProcessId);$agentHandle=$agent.Handle;if([IO.Path]::GetFullPath($agent.MainModule.FileName) -ne [IO.Path]::GetFullPath($expected)){throw 'Loaded diagnostic broker image changed'}
if($agent.Id -eq $PID -or $agent.Id -eq $OwnerPid){throw 'The operator and ordinary receiver must remain running'}
Add-Type -TypeDefinition @'
using System;using System.Runtime.InteropServices;
public static class MuSyntheticThreadPause {
 [DllImport("kernel32.dll",SetLastError=true)] public static extern IntPtr OpenThread(uint access,bool inherit,uint id);
 [DllImport("kernel32.dll",SetLastError=true)] public static extern uint SuspendThread(IntPtr handle);
 [DllImport("kernel32.dll",SetLastError=true)] public static extern uint GetProcessIdOfThread(IntPtr handle);
 [DllImport("kernel32.dll",SetLastError=true)] public static extern uint ResumeThread(IntPtr handle);
 [DllImport("kernel32.dll")] public static extern uint WaitForSingleObject(IntPtr handle,uint milliseconds);
 [DllImport("kernel32.dll")] public static extern bool CloseHandle(IntPtr handle);
}
'@
$handles=[Collections.Generic.List[IntPtr]]::new();$seen=[Collections.Generic.HashSet[int]]::new();$stable=0;$errors=@()
try{
 for($round=0;$round -lt 16 -and $stable -lt 2;$round++){
  $agent.Refresh();$added=0;foreach($thread in $agent.Threads){if($seen.Contains($thread.Id)){continue};if($seen.Count -ge 256){throw 'Bounded synthetic thread inventory exceeded'};$handle=[MuSyntheticThreadPause]::OpenThread(0x100802,$false,[uint32]$thread.Id);if($handle -eq [IntPtr]::Zero){continue};if([MuSyntheticThreadPause]::GetProcessIdOfThread($handle) -ne [uint32]$agent.Id){[void][MuSyntheticThreadPause]::CloseHandle($handle);throw 'A diagnostic thread changed process ownership'};$previous=[MuSyntheticThreadPause]::SuspendThread($handle);if($previous -eq [uint32]::MaxValue){[void][MuSyntheticThreadPause]::CloseHandle($handle);throw 'Synthetic thread pause failed'};if($previous -ne 0){[void][MuSyntheticThreadPause]::ResumeThread($handle);[void][MuSyntheticThreadPause]::CloseHandle($handle);throw 'The diagnostic thread was already suspended'};$handles.Add($handle);[void]$seen.Add($thread.Id);$added++};if($added){$stable=0}else{$stable++};Start-Sleep -Milliseconds 20
 }
 if($stable -lt 2 -or -not $handles.Count){throw 'The exact native process was not completely paused'}
 Receipt 'paused' @{agentPid=$agent.Id;ownerPid=$OwnerPid;suspendedThreads=$handles.Count;powerSession=$request.powerSession;actualOsSleep=$false}
 Start-Sleep -Seconds 8
}finally{
 foreach($handle in $handles){$result=[MuSyntheticThreadPause]::ResumeThread($handle);if($result -eq [uint32]::MaxValue -and [MuSyntheticThreadPause]::WaitForSingleObject($handle,0) -ne 0){$errors+='An original synthetic thread did not resume'};[void][MuSyntheticThreadPause]::CloseHandle($handle)};$agent.Dispose()
}
if($errors.Count){throw ($errors -join '; ')};Receipt 'resumed' @{resumed=$true;actualOsSleep=$false}
